select public.import_products($json$[{"sku":"SU-0004914","name":"Planche de chasse sous-marine PLUMA BEUCHAT","brand":"BEUCHAT","category_path":["plongee","chasse-sous-marine","signalisation"],"description":"Planche de chasse sous-marine et d'apnée PLUMA BEUCHATLa nouvelle planche de chasse sous marine et d'apnée Pluma Beuchat sert à la fois d'aide de palmage, de bouée de signalisation, de flotteur accroche poisson et de transport pour votre arbalète et matériel de chasse sous-marine. Hydrodynamique, elle assure votre sécurité en surface à petit prix !Constituée d'une enveloppe en nylon haute résistance, le planche de chasse et d'apnée Pluma Beuchat assure votre sécurité en surface notamment grâce à sa couleur rouge. Elle est équipée de trois vessies indépendantes, deux latérales et une centrale ; qui assurent une flottabilité stable et sécurisante, même en pleine mer.La planche est aussi livrée avec deux pavillons montés sur mât, garantissant une bonne visibilité et donc une meilleure sécurité lors des sorties.Elle est conçue pour offrir un véritable confort de nage, notamment lors de longs déplacements grâce à son excellent soutien au palmage. Son coussin central permet non seulement de se reposer facilement en surface, mais améliore également l’hydrodynamisme pour une progression fluide dans l’eau.Pratique pour les chasseurs sous-marins, elle dispose d’un système d’attache ingénieux permettant de fixer jusqu’à deux arbalètes grâce à des crochets solides et des anneaux en caoutchouc.Elle permet également de transporter votre équipement, vos proies avec 8 anneaux d’accrochage d’équipement, 3 anneaux de tractage et de mouillage pouvant aussi servir à l’accrochage d’équipement de chasse sous-marine.Un compartiment de rangement à l’avant fermé par un rabat velcro permet également d'entreposer d'autres accessoires. Des cordons élastiques sur le coussin central sécurisent le matériel du chasseur.La planche de chasse et d'apnée Pluma Beuchat est l'équipement indispensable, fiable et confortable, pensé pour les passionnés d'apnée et de chasse sous-marine exigeants.Informations techniques :Matériau Nylon haute résistanceTransport d'arbalètes 28 anneaux d´accrochage (Ø 40mm)3 anneaux (Ø 50mm) de tractage et de mouillageCouleur RougePoids 1430kgContenu du colis1x planche de chasse et d'apnée PLUMA BEUCHAT, 1x vendu dans un sac mesh réutilisable avec deux pavillons","price_cents":9600,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0004914/01-pl-10760-pl-10760-picture_1-pl-10760-1.jpg"},{"sku":"SU-0004923","name":"PLAQUETTE DE NATATION HAND PADDLE LARGE SEAC SUB","brand":"SEAC","category_path":["plongee","longe-cote-marche-aquatique","equipement-pour-le-longe-cote"],"description":"PLAQUETTE DE NATATION HAND PADDLE LARGE SEAC SUBNagez avec les plaquettes de nage HAND PADDLE SEAC SUB permettant d'accroître la résistance dans l'eau et ainsi travailler efficacement votre renforcement musculaire.Les palmes pour les mains Seac Hand paddle sont parfaites pour renforcer la partie supérieure du corps pendant la formation de natation. Disponibles en trois tailles, les palmes Seac Hand paddle sont fixées par de souples élastiques qui les tiennent fermement aux mains. De petits trous sur les palettes permettent le passage de l'eau pour une sensation plus naturelle.Accessoires pour les mains idéaux pour la formation des membres supérieurs dans la natation.Palettes perforées pour optimiser la sensation réelle de contact avec l'eau pendant les coups.Dimensions taille L 21 x 16 cm.Élastiques souples réglables et résistants.","price_cents":999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0004923/01-hand_paddle_9946bc_01_800.jpg"},{"sku":"SU-0004924","name":"PLAQUETTE DE NATATION HAND PADDLE MEDIUM SEAC SUB","brand":"SEAC","category_path":["plongee","longe-cote-marche-aquatique","equipement-pour-le-longe-cote"],"description":"PLAQUETTE DE NATATION HAND PADDLE MEDIUM SEAC SUBNagez avec les plaquettes de nage HAND PADDL